const book = (id, units, extra = {}) => ({
  service: "studio", action: "book", tenant: "orchid", day: "2025-04-02", id, units, ...extra
});
const renew = (previous, id, extra = {}) => ({
  service: "studio", action: "renew", previous, id, day: "2025-05-02", ...extra
});

test("Studio quotas preserve replay, conflict, cancellation and tenant/day accounting", () => {
  const dispatch = planner(catalog);
  const request = book("first", 7);
  assert.deepEqual(dispatch(request), {status: "booked", id: "first", remaining: 1});
  assert.equal(dispatch(book("last", 1)).status, "booked");
  const before = dispatch({service: "studio", action: "summary"});
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 6}).status, "conflict");
  assert.deepEqual(dispatch(book("overflow", 1)), {status: "full", id: "overflow", remaining: 0});
  assert.deepEqual(dispatch({service: "studio", action: "summary"}), before);
  assert.equal(dispatch(book("other-day", 8, {day: "2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("other-tenant", 5, {tenant: "fern"})).status, "booked");
  assert.equal(dispatch({service: "studio", action: "cancel", id: "first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch(book("replacement", 7)).status, "booked");
  assert.deepEqual(dispatch({service: "studio", action: "usage", tenant: "orchid", day: "2025-04-02"}), {units: 8});
});

test("renewals inherit tenant/units and use Studio admission with normal replay semantics", () => {
  const dispatch = planner(catalog);
  dispatch(book("first", 7));
  const next = renew("first", "next");
  assert.deepEqual(dispatch(next), {status: "booked", id: "next", remaining: 1});
  dispatch(book("may-top-up", 1, {day: "2025-05-02"}));
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units: 6}).status, "conflict");
  assert.deepEqual(dispatch(renew("first", "too-many")), {status: "full", id: "too-many", remaining: 0});
  dispatch({service: "studio", action: "cancel", id: "next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch(renew("first", "replacement")).status, "booked");
  dispatch({service: "studio", action: "cancel", id: "first"});
  assert.equal(dispatch(renew("first", "after-cancel")).status, "missing");
  assert.equal(dispatch(renew("unknown", "not-created")).status, "missing");
});

test("lower allocations and unlisted tenants apply to both booking and renewal", () => {
  for (const [tenant, cap] of [["iris", 2], ["fern", 5]]) {
    const dispatch = planner(catalog);
    assert.equal(dispatch(book("too-big", cap + 1, {tenant})).status, "full");
    assert.equal(dispatch(book("original", cap, {tenant})).status, "booked");
    assert.equal(dispatch(renew("original", "too-big-renewal", {units: cap + 1})).status, "full");
    assert.deepEqual(dispatch(renew("original", "renewed")), {status: "booked", id: "renewed", remaining: 0});
  }
});

test("imports count towards quotas without admission; Archive retains the default", () => {
  const dispatch = planner(catalog);
  assert.equal(dispatch(book("backfill", 10, {action: "import"})).status, "imported");
  assert.deepEqual(dispatch(book("blocked", 1)), {status: "full", id: "blocked", remaining: 0});
  assert.equal(dispatch(book("backfill", 10)).status, "replay");
  assert.equal(dispatch(renew("backfill", "oversized-renewal")).status, "full");
  assert.equal(dispatch(book("archive-too-big", 7, {service: "archive"})).status, "full");
  assert.equal(dispatch(book("archive-first", 5, {service: "archive"})).status, "booked");
  assert.equal(dispatch(renew("archive-first", "archive-next", {service: "archive", units: 6})).status, "full");
  assert.equal(dispatch(renew("archive-first", "archive-next", {service: "archive"})).status, "booked");
  assert.equal(apply(dispatch, book("bad", 0)).status, "invalid");
  assert.equal(apply(dispatch, renew("backfill", "invalid-renewal", {day: "2025-02-30"})).status, "invalid");
});

test("staging a Studio release preserves the queue and is idempotent", () => {
